     9	static bool load_buffer (RBinFile *bf, void **bin_obj, RBuffer *b, ut64 loadaddr, Sdb *sdb) {
    10	        ut64 size;
    11	        const ut8 *buf = r_buf_data (b, &size);
    12	        *bin_obj = r_bin_internal_omf_load (buf, size);
    13	        return *bin_obj != NULL;
    14	}
