    16	static bool load(RBinFile *bf) {
    17	        r_return_val_if_fail (bf && bf->o, false);
    18	        return load_buffer (bf, &bf->o->bin_obj, bf->buf, bf->o->loadaddr, bf->sdb);
    19	}
