    76	static RList *entries(RBinFile *bf) {
    77	        RList *ret;
    78	        RBinAddr *addr;
    79	
    80	        if (!(ret = r_list_newf (free))) {
    81	                return NULL;
    82	        }
    83	        if (!(addr = R_NEW0 (RBinAddr))) {
    84	                r_list_free (ret);
    85	                return NULL;
    86	        }
    87	        if (!r_bin_omf_get_entry (bf->o->bin_obj, addr)) {
    88	                R_FREE (addr);
    89	        } else {
    90	                r_list_append (ret, addr);
    91	        }
    92	        return ret;
    93	}
