    95	static RList *sections(RBinFile *bf) {
    96	        RList *ret;
    97	        ut32 ct_omf_sect = 0;
    98	
    99	        if (!bf || !bf->o || !bf->o->bin_obj) {
   100	                return NULL;
   101	        }
   102	        r_bin_omf_obj *obj = bf->o->bin_obj;
   103	
   104	        if (!(ret = r_list_new ())) {
   105	                return NULL;
   106	        }
   107	
   108	        while (ct_omf_sect < obj->nb_section) {
   109	                if (!r_bin_omf_send_sections (ret,\
   110	                            obj->sections[ct_omf_sect++], bf->o->bin_obj)) {
   111	                        return ret;
   112	                }
   113	        }
   114	        return ret;
   115	}
