   117	static RList *symbols(RBinFile *bf) {
   118	        RList *ret;
   119	        RBinSymbol *sym;
   120	        OMF_symbol *sym_omf;
   121	        int ct_sym = 0;
   122	        if (!bf || !bf->o || !bf->o->bin_obj) {
   123	                return NULL;
   124	        }
   125	        if (!(ret = r_list_new ())) {
   126	                return NULL;
   127	        }
   128	
   129	        ret->free = free;
   130	
   131	        while (ct_sym < ((r_bin_omf_obj *) bf->o->bin_obj)->nb_symbol) {
   132	                if (!(sym = R_NEW0 (RBinSymbol))) {
   133	                        return ret;
   134	                }
   135	                sym_omf = ((r_bin_omf_obj *) bf->o->bin_obj)->symbols[ct_sym++];
   136	                sym->name = strdup (sym_omf->name);
   137	                sym->forwarder = r_str_const ("NONE");
   138	                sym->paddr = r_bin_omf_get_paddr_sym (bf->o->bin_obj, sym_omf);
   139	                sym->vaddr = r_bin_omf_get_vaddr_sym (bf->o->bin_obj, sym_omf);
   140	                sym->ordinal = ct_sym;
   141	                sym->size = 0;
   142	                r_list_append (ret, sym);
   143	        }
   144	        return ret;
   145	}
